import functools
from fastapi.dependencies.utils import get_typed_signature
from typing import Any

# We simulate two different modules by using different functions' globals
def module_a_scope():
    class Model:
        pass

    def my_func(a: "Model"):
        return a

    return my_func, Model

def module_b_scope():
    def wrapper(func):
        @functools.wraps(func)
        def wrapped(*args, **kwargs):
            return func(*args, **kwargs)
        return wrapped
    return wrapper

my_func, Model = module_a_scope()
wrapper = module_b_scope()
wrapped_func = wrapper(my_func)

print(f"my_func globals: {my_func.__globals__ is my_func.__globals__}")
print(f"wrapped_func globals: {wrapped_func.__globals__ is wrapper.__globals__}")
print(f"Are globals same? {wrapped_func.__globals__ is my_func.__globals__}")

try:
    sig = get_typed_signature(wrapped_func)
    print("Success!")
except Exception as e:
    print(f"Failed as expected: {e}")

